arguments.content:
/* ShiftWise Design System — OKLCH Color Space */

/* ============================================
   CSS Custom Properties
   ============================================ */
:root {
  /* Brand Colors — OKLCH */
  --brand-primary: oklch(38% 0.18 264);        /* Deep navy blue */
  --brand-primary-light: oklch(50% 0.20 264);  /* Medium blue */
  --brand-primary-dark: oklch(26% 0.14 264);   /* Very dark navy */
  --brand-accent: oklch(58% 0.20 26);          /* Warm coral-red */
  --brand-accent-hover: oklch(50% 0.22 26);    /* Darker accent */
  --brand-accent-light: oklch(92% 0.06 26);    /* Pale accent tint */

  /* Neutrals */
  --gray-50:  oklch(98% 0.005 264);
  --gray-100: oklch(95% 0.008 264);
  --gray-200: oklch(90% 0.010 264);
  --gray-300: oklch(83% 0.012 264);
  --gray-400: oklch(70% 0.015 264);
  --gray-500: oklch(58% 0.018 264);
  --gray-600: oklch(46% 0.020 264);
  --gray-700: oklch(36% 0.020 264);
  --gray-800: oklch(26% 0.018 264);
  --gray-900: oklch(18% 0.015 264);

  /* Semantic */
  --text-primary: oklch(18% 0.015 264);
  --text-secondary: oklch(46% 0.020 264);
  --text-muted: oklch(60% 0.015 264);
  --text-on-dark: oklch(98% 0.005 264);
  --bg-page: oklch(99% 0.003 264);
  --bg-surface: oklch(100% 0 0);
  --bg-subtle: oklch(97% 0.006 264);
  --border-light: oklch(90% 0.010 264);
  --border-medium: oklch(83% 0.012 264);

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Typography */
  --font-display: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(18% 0.015 264 / 0.08), 0 1px 2px oklch(18% 0.015 264 / 0.06);
  --shadow-md: 0 4px 12px oklch(18% 0.015 264 / 0.10), 0 2px 6px oklch(18% 0.015 264 / 0.06);
  --shadow-lg: 0 12px 32px oklch(18% 0.015 264 / 0.12), 0 4px 12px oklch(18% 0.015 264 / 0.08);
  --shadow-xl: 0 24px 48px oklch(18% 0.015 264 / 0.16), 0 8px 20px oklch(18% 0.015 264 / 0.10);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* ============================================
   Reset & Base
   ============================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background-color: var(--bg-page);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

input, textarea, select {
  font-family: inherit;
}

/* ============================================
   Typography
   ============================================ */
.text-xs   { font-size: 0.75rem; line-height: 1.4; }
.text-sm   { font-size: 0.875rem; line-height: 1.5; }
.text-base { font-size: 1rem; line-height: 1.6; }
.text-lg   { font-size: 1.125rem; line-height: 1.55; }
.text-xl   { font-size: 1.25rem; line-height: 1.5; }
.text-2xl  { font-size: 1.5rem; line-height: 1.4; }
.text-3xl  { font-size: 1.875rem; line-height: 1.3; }
.text-4xl  { font-size: 2.25rem; line-height: 1.2; }
.text-5xl  { font-size: 3rem; line-height: 1.15; }
.text-6xl  { font-size: 3.75rem; line-height: 1.1; }

.font-normal   { font-weight: 400; }
.font-medium   { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold     { font-weight: 700; }
.font-extrabold{ font-weight: 800; }

.text-muted    { color: var(--text-muted); }
.text-secondary{ color: var(--text-secondary); }
.text-accent   { color: var(--brand-accent); }
.text-primary-brand { color: var(--brand-primary); }

/* ============================================
   Layout Utilities
   ============================================ */
.container {
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.container-narrow {
  width: 100%;
  max-width: 800px;
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.section {
  padding-block: var(--space-20);
}

.section-sm {
  padding-block: var(--space-12);
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-4 { gap: var(--space-4); }
.gap-6 { gap: var(--space-6); }
.gap-8 { gap: var(--space-8); }

.text-center { text-align: center; }

/* ============================================
   Navigation
   ============================================ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: oklch(100% 0 0 / 0.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-weight: 800;
  font-size: 1.35rem;
  color: var(--brand-primary);
  letter-spacing: -0.02em;
}

.nav-logo svg {
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--brand-accent);
  transform: scaleX(0);
  transition: transform var(--transition-fast);
  border-radius: var(--radius-full);
}

.nav-link:hover { color: var(--brand-primary); }
.nav-link:hover::after { transform: scaleX(1); }
.nav-link.active { color: var(--brand-primary); font-weight: 600; }
.nav-link.active::after { transform: scaleX(1); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}

.nav-hamburger:hover { background: var(--gray-100); }

.nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: var(--radius-full);
  transition: transform var(--transition-base), opacity var(--transition-base);
}

.nav-hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-hamburger.open span:nth-child(2) { opacity: 0; }
.nav-hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Mobile Drawer */
.nav-drawer {
  display: none;
  position: fixed;
  top: 68px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-surface);
  z-index: 99;
  padding: var(--space-8) var(--space-6);
  flex-direction: column;
  gap: var(--space-2);
  transform: translateX(100%);
  transition: transform var(--transition-base);
  overflow-y: auto;
}

.nav-drawer.open {
  transform: translateX(0);
}

.nav-drawer .nav-link {
  font-size: 1.125rem;
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--border-light);
  display: block;
}

.nav-drawer .nav-link::after { display: none; }

.nav-drawer-actions {
  margin-top: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 0.65rem 1.5rem;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition: all var(--transition-fast);
  white-space: nowrap;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--brand-accent);
  color: white;
  border-color: var(--brand-accent);
}

.btn-primary:hover {
  background: var(--brand-accent-hover);
  border-color: var(--brand-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px oklch(58% 0.20 26 / 0.35);
}

.btn-outline {
  background: transparent;
  color: var(--brand-primary);
  border-color: var(--brand-primary);
}

.btn-outline:hover {
  background: var(--brand-primary);
  color: white;
  transform: translateY(-1px);
}

.btn-outline-white {
  background: transparent;
  color: white;
  border-color: oklch(100% 0 0 / 0.5);
}

.btn-outline-white:hover {
  background: oklch(100% 0 0 / 0.12);
  border-color: white;
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border-color: transparent;
}

.btn-ghost:hover {
  background: var(--gray-100);
  color: var(--text-primary);
}

.btn-lg {
  padding: 0.85rem 2rem;
  font-size: 1.0625rem;
  border-radius: var(--radius-lg);
}

.btn-sm {
  padding: 0.45rem 1rem;
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
}

.btn-full { width: 100%; }

/* ============================================
   Hero Section
   ============================================ */
.hero {
  background: linear-gradient(135deg,
    var(--brand-primary-dark) 0%,
    var(--brand-primary) 50%,
    oklch(44% 0.19 255) 100%
  );
  color: white;
  padding-block: var(--space-24);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 30% 60%, oklch(100% 0 0 / 0.04) 0%, transparent 50%),
                    radial-gradient(circle at 80% 20%, oklch(58% 0.20 26 / 0.15) 0%, transparent 45%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
  position: relative;
  z-index: 1;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: oklch(100% 0 0 / 0.12);
  border: 1px solid oklch(100% 0 0 / 0.2);
  border-radius: var(--radius-full);
  padding: 0.35rem 1rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: var(--space-5);
  color: oklch(90% 0.06 26);
}

.hero-title {
  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-5);
}

.hero-title em {
  font-style: normal;
  color: oklch(78% 0.16 26);
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: oklch(88% 0.04 264);
  margin-bottom: var(--space-8);
  max-width: 520px;
}

.hero-actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

.hero-card {
  background: oklch(100% 0 0 / 0.08);
  backdrop-filter: blur(20px);
  border: 1px solid oklch(100% 0 0 / 0.15);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  position: relative;
}

.hero-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-4);
}

.hero-card-title {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: oklch(80% 0.05 264);
}

.schedule-grid {
  display: grid;
  gap: var(--space-2);
}

.schedule-row {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: var(--space-3);
  align-items: center;
}

.schedule-name {
  font-size: 0.8125rem;
  font-weight: 500;
  color: oklch(88% 0.04 264);
}

.schedule-shifts {
  display: flex;
  gap: var(--space-1);
}

.shift-block {
  height: 28px;
  border-radius: var(--radius-sm);
  flex: 1;
  min-width: 0;
}

.shift-morning { background: oklch(72% 0.16 160 / 0.8); }
.shift-afternoon { background: oklch(65% 0.18 26 / 0.8); }
.shift-evening { background: oklch(55% 0.16 264 / 0.8); }
.shift-empty { background: oklch(100% 0 0 / 0.08); }

.hero-badge {
  position: absolute;
  background: white;
  border-radius: var(--radius-lg);
  padding: var(--space-3) var(--space-4);
  box-shadow: var(--shadow-xl);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.hero-badge-right {
  bottom: -24px;
  right: -16px;
}

.hero-badge-left {
  top: -20px;
  left: -16px;
}

.badge-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.badge-icon-green { background: oklch(92% 0.08 160); }
.badge-icon-blue { background: oklch(92% 0.08 264); }

.badge-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
}

.badge-value {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

/* ============================================
   Section Headers
   ============================================ */
.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.section-eyebrow {
  display: inline-block;
  color: var(--brand-accent);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: var(--space-3);
}

.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  color: var(--text-primary);
  margin-bottom: var(--space-4);
  line-height: 1.2;
}

.section-subtitle {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  max-width: 560px;
  margin-inline: auto;
  line-height: 1.7;
}

/* ============================================
   Feature Cards
   ============================================ */
.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--brand-accent), var(--brand-primary));
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.feature-card:hover {
  border-color: var(--border-medium);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.feature-card:hover::before {
  transform: scaleX(1);
}

.feature-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
  background: var(--bg-subtle);
}

.feature-icon-blue { background: oklch(93% 0.06 264); color: var(--brand-primary); }
.feature-icon-red  { background: oklch(95% 0.05 26); color: var(--brand-accent); }
.feature-icon-green{ background: oklch(93% 0.06 160); color: oklch(40% 0.15 160); }
.feature-icon-purple{ background: oklch(93% 0.06 300); color: oklch(40% 0.15 300); }
.feature-icon-orange{ background: oklch(95% 0.07 60); color: oklch(45% 0.18 60); }

.feature-card h3 {
  font-size: 1.1875rem;
  font-weight: 700;
  margin-bottom: var(--space-3);
  letter-spacing: -0.01em;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.65;
}

/* ============================================
   Stats Banner
   ============================================ */
.stats-section {
  background: var(--brand-primary);
  padding-block: var(--space-16);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
  text-align: center;
}

.stat-item {}

.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: white;
  letter-spacing: -0.03em;
  line-height: 1;
  margin-bottom: var(--space-2);
}

.stat-value .accent { color: oklch(78% 0.16 26); }

.stat-label {
  font-size: 0.9375rem;
  color: oklch(78% 0.06 264);
  font-weight: 500;
}

/* ============================================
   How It Works
   ============================================ */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 28px;
  left: 10%;
  right: 10%;
  height: 2px;
  background: linear-gradient(90deg, var(--brand-accent), var(--brand-primary));
  opacity: 0.2;
}

.step-item {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--brand-primary);
  color: white;
  font-size: 1.25rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  position: relative;
  z-index: 1;
  box-shadow: 0 0 0 6px oklch(38% 0.18 264 / 0.1);
}

.step-title {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: var(--space-2);
  letter-spacing: -0.01em;
}

.step-desc {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Testimonials
   ============================================ */
.testimonials-section {
  background: var(--bg-subtle);
}

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform var(--transition-slow) cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 var(--space-4);
}

.testimonial-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-10) var(--space-12);
  max-width: 720px;
  margin-inline: auto;
  position: relative;
  box-shadow: var(--shadow-md);
}

.testimonial-quote-icon {
  color: var(--brand-accent);
  margin-bottom: var(--space-5);
  opacity: 0.4;
}

.testimonial-text {
  font-size: 1.1875rem;
  line-height: 1.7;
  color: var(--text-primary);
  font-style: italic;
  margin-bottom: var(--space-6);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}

.avatar-1 { background: linear-gradient(135deg, oklch(58% 0.20 26), oklch(50% 0.22 26)); }
.avatar-2 { background: linear-gradient(135deg, var(--brand-primary-light), var(--brand-primary)); }
.avatar-3 { background: linear-gradient(135deg, oklch(50% 0.15 160), oklch(40% 0.15 160)); }

.author-name {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-primary);
}

.author-role {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.stars {
  display: flex;
  gap: 3px;
  margin-bottom: var(--space-4);
}

.star {
  color: oklch(72% 0.18 75);
  font-size: 1rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--bg-surface);
  border: 1px solid var(--border-medium);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  box-shadow: var(--shadow-sm);
}

.carousel-btn:hover {
  background: var(--brand-primary);
  color: white;
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-md);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--border-medium);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-dot.active {
  width: 24px;
  background: var(--brand-accent);
}

/* ============================================
   Pricing Teaser / Table
   ============================================ */
.pricing-card {
  background: var(--bg-surface);
  border: 2px solid var(--border-light);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  transition: all var(--transition-base);
  position: relative;
  display: flex;
  flex-direction: column;
}

.pricing-card.featured {
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-xl);
  transform: translateY(-8px);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--brand-accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 0.3rem 1rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
}

.pricing-plan {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--brand-accent);
  margin-bottom: var(--space-3);
}

.pricing-price {
  font-size: 3rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: var(--space-1);
}

.pricing-price sup {
  font-size: 1.25rem;
  font-weight: 600;
  vertical-align: super;
  letter-spacing: 0;
}

.pricing-price .period {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0;
}

.pricing-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: var(--space-6);
  line-height: 1.5;
}

.pricing-divider {
  height: 1px;
  background: var(--border-light);
  margin-block: var(--space-6);
}

.pricing-features {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.pricing-feature {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.pricing-feature .check {
  color: oklch(52% 0.15 160);
  flex-shrink: 0;
  margin-top: 1px;
}

.pricing-feature .dash {
  color: var(--text-muted);
  flex-shrink: 0;
  margin-top: 1px;
}

/* Pricing Toggle */
.pricing-toggle-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.toggle-label.active { color: var(--text-primary); font-weight: 600; }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

.toggle-slider {
  position: absolute;
  inset: 0;
  background: var(--border-medium);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.toggle-slider::before {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: white;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-fast);
}

.toggle-switch input:checked + .toggle-slider {
  background: var(--brand-primary);
}

.toggle-switch input:checked + .toggle-slider::before {
  transform: translateX(24px);
}

.savings-badge {
  background: oklch(92% 0.08 160);
  color: oklch(35% 0.14 160);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-full);
}

/* ============================================
   FAQ Accordion
   ============================================ */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-width: 760px;
  margin-inline: auto;
}

.faq-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition-fast);
}

.faq-item.open {
  box-shadow: var(--shadow-md);
  border-color: var(--border-medium);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  cursor: pointer;
  gap: var(--space-4);
  user-select: none;
}

.faq-question-text {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.faq-item.open .faq-icon {
  background: var(--brand-primary);
  color: white;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow) cubic-bezier(0.4, 0, 0.2, 1);
}

.faq-answer-inner {
  padding: 0 var(--space-6) var(--space-5);
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.9375rem;
}

/* ============================================
   CTA Section
   ============================================ */
.cta-section {
  background: linear-gradient(135deg,
    var(--brand-primary-dark) 0%,
    var(--brand-primary) 100%
  );
  padding-block: var(--space-20);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 20% 80%, oklch(58% 0.20 26 / 0.12) 0%, transparent 50%),
    radial-gradient(circle at 85% 15%, oklch(100% 0 0 / 0.04) 0%, transparent 45%);
  pointer-events: none;
}

.cta-section .section-title {
  color: white;
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
}

.cta-section .section-subtitle {
  color: oklch(82% 0.06 264);
}

.cta-actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
  margin-top: var(--space-8);
}

/* ============================================
   Contact Form
   ============================================ */
.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
}

.form-input,
.form-textarea,
.form-select {
  padding: 0.7rem 1rem;
  border: 1.5px solid var(--border-medium);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--text-primary);
  background: var(--bg-surface);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  width: 100%;
}

.form-input::placeholder,
.form-textarea::placeholder {
  color: var(--text-muted);
}

.form-input:focus,
.form-textarea:focus,
.form-select:focus {
  outline: none;
  border-color: var(--brand-primary);
  box-shadow: 0 0 0 3px oklch(38% 0.18 264 / 0.12);
}

.form-input.error,
.form-textarea.error {
  border-color: var(--brand-accent);
  box-shadow: 0 0 0 3px oklch(58% 0.20 26 / 0.1);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--brand-accent);
  font-weight: 500;
  display: none;
}

.form-error.visible { display: block; }

.form-textarea { resize: vertical; min-height: 130px; }

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5);
}

.form-success {
  display: none;
  background: oklch(92% 0.08 160);
  border: 1px solid oklch(72% 0.14 160);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  text-align: center;
}

.form-success.visible { display: block; }

.form-success h3 {
  color: oklch(35% 0.14 160);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.form-success p {
  color: oklch(40% 0.12 160);
}

/* ============================================
   Integration Grid
   ============================================ */
.integration-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-5);
}

.integration-category {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-base);
}

.integration-category:hover {
  border-color: var(--brand-primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.integration-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-3);
}

.integration-category h4 {
  font-weight: 700;
  font-size: 0.9375rem;
  margin-bottom: var(--space-2);
}

.integration-partners {
  font-size: 0.8125rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* ============================================
   Team Cards
   ============================================ */
.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.team-card {
  text-align: center;
  padding: var(--space-6);
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  transition: all var(--transition-base);
}

.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.team-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  margin: 0 auto var(--space-4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  font-weight: 800;
  color: white;
}

.team-name { font-weight: 700; font-size: 1.0625rem; margin-bottom: var(--space-1); }
.team-role { font-size: 0.875rem; color: var(--text-muted); }

/* ============================================
   Page Hero (Inner Pages)
   ============================================ */
.page-hero {
  background: linear-gradient(135deg, var(--brand-primary-dark) 0%, var(--brand-primary) 100%);
  color: white;
  padding-block: var(--space-20);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 30% 70%, oklch(100% 0 0 / 0.04) 0%, transparent 50%);
  pointer-events: none;
}

.page-hero-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: var(--space-4);
  position: relative;
}

.page-hero-subtitle {
  font-size: 1.125rem;
  color: oklch(85% 0.05 264);
  max-width: 580px;
  margin-inline: auto;
  line-height: 1.7;
  position: relative;
}

/* ============================================
   Feature Detail Sections
   ============================================ */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-content h2 {
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: var(--space-4);
  line-height: 1.2;
}

.feature-detail-content p {
  color: var(--text-secondary);
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: var(--space-5);
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.feature-list-item .check-icon {
  color: oklch(52% 0.15 160);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-visual-box {
  background: linear-gradient(135deg, var(--brand-primary-dark), var(--brand-primary));
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.feature-visual-box::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 30%, oklch(58% 0.20 26 / 0.15) 0%, transparent 50%);
}

.feature-mockup {
  background: oklch(100% 0 0 / 0.1);
  backdrop-filter: blur(10px);
  border: 1px solid oklch(100% 0 0 / 0.2);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  width: 100%;
  position: relative;
}

.mockup-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid oklch(100% 0 0 / 0.15);
}

.mockup-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.mockup-bar {
  height: 10px;
  border-radius: var(--radius-full);
  background: oklch(100% 0 0 / 0.15);
  flex: 1;
}

.mockup-row {
  display: flex;
  gap: var(--space-3);
  margin-bottom: var(--space-2);
  align-items: center;
}

.mockup-avatar-sm {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: oklch(100% 0 0 / 0.2);
  flex-shrink: 0;
}

.mockup-text-line {
  height: 8px;
  border-radius: var(--radius-full);
  background: oklch(100% 0 0 / 0.18);
}

.mockup-chip {
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 0.6875rem;
  font-weight: 600;
  color: white;
}

/* ============================================
   Office Locations
   ============================================ */
.office-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.office-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  text-align: center;
  transition: all var(--transition-base);
}

.office-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.office-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.office-city {
  font-weight: 700;
  font-size: 1.0625rem;
  margin-bottom: var(--space-1);
}

.office-detail {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background: var(--brand-primary-dark);
  color: oklch(80% 0.05 264);
  padding-block: var(--space-16) var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

.footer-brand {}

.footer-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 1.35rem;
  font-weight: 800;
  color: white;
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.footer-tagline {
  font-size: 0.9rem;
  line-height: 1.65;
  color: oklch(68% 0.05 264);
  max-width: 240px;
}

.footer-col-title {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: white;
  margin-bottom: var(--space-4);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-link {
  font-size: 0.9rem;
  color: oklch(68% 0.05 264);
  transition: color var(--transition-fast);
}

.footer-link:hover { color: white; }

.footer-bottom {
  border-top: 1px solid oklch(100% 0 0 / 0.08);
  padding-top: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-copy {
  font-size: 0.875rem;
  color: oklch(55% 0.04 264);
}

.footer-social {
  display: flex;
  gap: var(--space-3);
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background: oklch(100% 0 0 / 0.07);
  display: flex;
  align-items: center;
  justify-content: center;
  color: oklch(68% 0.05 264);
  font-size: 0.9rem;
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: var(--brand-accent);
  color: white;
}

/* ============================================
   Utility
   ============================================ */
.bg-subtle { background: var(--bg-subtle); }
.bg-surface { background: var(--bg-surface); }

/* Pricing Table Full */
.pricing-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.pricing-table th {
  padding: var(--space-5) var(--space-6);
  font-size: 0.9375rem;
  font-weight: 700;
  text-align: center;
  background: var(--gray-50);
  border-bottom: 2px solid var(--border-light);
}

.pricing-table th.plan-highlighted {
  background: var(--brand-primary);
  color: white;
}

.pricing-table td {
  padding: var(--space-4) var(--space-6);
  font-size: 0.9375rem;
  text-align: center;
  border-bottom: 1px solid var(--border-light);
  vertical-align: middle;
}

.pricing-table td:first-child {
  text-align: left;
  font-weight: 500;
  color: var(--text-primary);
}

.pricing-table tr:last-child td { border-bottom: none; }
.pricing-table tr:hover { background: var(--gray-50); }

.pricing-table .check-cell { color: oklch(52% 0.15 160); font-size: 1.1rem; }
.pricing-table .dash-cell { color: var(--gray-400); }

/* ============================================
   Animations
   ============================================ */
@keyframes countUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

.animate-fade-in {
  animation: fadeSlideIn 0.6s ease forwards;
}

.stat-item {
  animation: countUp 0.6s ease both;
}

.stat-item:nth-child(1) { animation-delay: 0.1s; }
.stat-item:nth-child(2) { animation-delay: 0.2s; }
.stat-item:nth-child(3) { animation-delay: 0.3s; }
.stat-item:nth-child(4) { animation-delay: 0.4s; }

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; gap: var(--space-10); }
  .hero-visual { display: none; }
  .hero-subtitle { max-width: 100%; }
  .feature-detail { grid-template-columns: 1fr; gap: var(--space-10); }
  .feature-detail.reverse { direction: ltr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; gap: var(--space-8); }
  .steps-grid::before { display: none; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: var(--space-10); }
  .team-grid { grid-template-columns: 1fr 1fr; }
  .integration-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-actions { display: none; }
  .nav-hamburger { display: flex; }
  .nav-drawer { display: flex; }

  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr 1fr; }

  .hero { padding-block: var(--space-16); }
  .hero-actions { flex-direction: column; align-items: flex-start; }

  .section { padding-block: var(--space-12); }

  .testimonial-card { padding: var(--space-8) var(--space-6); }
